python3 -c '
# Let check all sample currencies and their decimal precision.
import json, glob

curs = {}
for p in sorted(glob.glob("/app/samples/*.json")):
    d = json.load(open(p))
    for r in d["records"]:
        c = r["currency"]
        amt = r["amount"].lstrip("-")
        if "." in amt:
            dec = len(amt.split(".")[1])
        else:
            dec = 0
        curs.setdefault(c, set()).add(dec)

print("Currency decimals mapping:")
for c, decs in sorted(curs.items()):
    print(f"  {c}: {decs}")
'

