for p in sorted(glob.glob("/app/samples/*.json")):
    d = json.load(open(p))
    for r in d["records"]:
        amt = r["amount"]
        if "." in amt:
            whole, frac = amt.split(".")
            # check if frac length is always standard for that currency
            c = r["currency"]
            if c in ("USD", "EUR", "GBP", "CHF", "SGD") and len(frac) != 2:
                print("Mismatch in 2-decimal cur:", r)
            if c == "KWD" and len(frac) != 3:
                print("Mismatch in 3-decimal cur:", r)
        else:
            if r["currency"] != "JPY":
                print("No decimal point for non-JPY:", r)
'

